"""从 eval 输出目录提取 accuracy + unparseable rate + gen_text 长度统计"""
import argparse, json, os, sys

def extract(eval_dir):
    pred_file = None
    # 优先查 *_predictions.jsonl
    for f in sorted(os.listdir(eval_dir)):
        if f.endswith("_predictions.jsonl"):
            pred_file = os.path.join(eval_dir, f)
            break
    # 次选固定名
    if not pred_file:
        for c in ["predictions.jsonl", "results_incremental.jsonl", "results.jsonl"]:
            p = os.path.join(eval_dir, c)
            if os.path.exists(p):
                pred_file = p
                break
    # 兜底：子目录任意 jsonl
    if not pred_file:
        for root, dirs, files in os.walk(eval_dir):
            for f in files:
                if f.endswith(".jsonl"):
                    pred_file = os.path.join(root, f)
                    break
            if pred_file:
                break

    if not pred_file:
        print(f"ERROR: No prediction file found in {eval_dir}")
        return None

    total = 0
    correct = 0
    unparseable = 0
    gen_lengths = []

    with open(pred_file) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            total += 1
            if obj.get("correct", obj.get("is_correct", 0)):
                correct += 1
            if "unparseable" in obj:
                if obj["unparseable"]:
                    unparseable += 1
            else:
                gen_text = obj.get("gen_text", obj.get("generated_text", obj.get("prediction", "")))
                if "PASS" not in gen_text.upper() and "FAIL" not in gen_text.upper():
                    unparseable += 1
            gen_text = obj.get("gen_text", obj.get("generated_text", obj.get("prediction", "")))
            gen_lengths.append(len(gen_text))

    if total == 0:
        print("ERROR: Empty prediction file")
        return None

    accuracy = correct / total * 100
    unparseable_rate = unparseable / total * 100
    avg_gen_len = sum(gen_lengths) / len(gen_lengths) if gen_lengths else 0

    result = {
        "eval_dir": eval_dir,
        "pred_file": pred_file,
        "total": total,
        "correct": correct,
        "accuracy": round(accuracy, 2),
        "unparseable": unparseable,
        "unparseable_rate": round(unparseable_rate, 2),
        "avg_gen_length": round(avg_gen_len, 1),
    }
    return result

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("eval_dir", help="Path to eval output directory")
    parser.add_argument("--output", help="Write JSON result to file")
    args = parser.parse_args()

    result = extract(args.eval_dir)
    if result:
        print(json.dumps(result, indent=2))
        if args.output:
            with open(args.output, "w") as f:
                json.dump(result, f, indent=2)
            print(f"Saved to {args.output}")

        if result["unparseable_rate"] < 50:
            print(f"\nALERT: unparseable_rate={result['unparseable_rate']}% < 50% — may not be repo-level CWM!")
            sys.exit(2)
    else:
        sys.exit(1)
